from sympy.core import Mul
from sympy.core.function import count_ops
from sympy.core.traversal import preorder_traversal, bottom_up
from sympy.functions.combinatorial.factorials import binomial, factorial
from sympy.functions import gamma
from sympy.simplify.gammasimp import gammasimp, _gammasimp

from sympy.utilities.timeutils import timethis


@timethis('combsimp')
def combsimp(expr):
    r"""
    Simplify combinatorial expressions.

    Explanation
    ===========

    This function takes as input an expression containing factorials,
    binomials, Pochhammer symbol and other "combinatorial" functions,
    and tries to minimize the number of those functions and reduce
    the size of their arguments.

    The algorithm works by rewriting all combinatorial functions as
    gamma functions and applying gammasimp() except simplification
    steps that may make an integer argument non-integer. See docstring
    of gammasimp for more information.

    Then it rewrites expression in terms of factorials and binomials by
    rewriting gammas as factorials and converting (a+b)!/a!b! into
    binomials.

    If expression has gamma functions or combinatorial functions
    with non-integer argument, it is automatically passed to gammasimp.

    Examples
    ========

    >>> from sympy.simplify import combsimp
    >>> from sympy import factorial, binomial, symbols
    >>> n, k = symbols('n k', integer = True)

    >>> combsimp(factorial(n)/factorial(n - 3))
    n*(n - 2)*(n - 1)
    >>> combsimp(binomial(n+1, k+1)/binomial(n, k))
    (n + 1)/(k + 1)

    """

    expr = expr.rewrite(gamma, piecewise=False)
    if any(isinstance(node, gamma) and not node.args[0].is_integer
        for node in preorder_traversal(expr)):
        return gammasimp(expr)

    expr = _gammasimp(expr, as_comb = True)
    expr = _gamma_as_comb(expr)
    return expr


def _gamma_as_comb(expr):
    """
    Helper function for combsimp.

    Rewrites expression in terms of factorials and binomials
    """

    expr = expr.rewrite(factorial)

    def f(rv):
        if not rv.is_Mul:
            return rv
        rvd = rv.as_powers_dict()
        nd_fact_args = [[], []] # numerator, denominator

        for k in rvd:
            if isinstance(k, factorial) and rvd[k].is_Integer:
                if rvd[k].is_positive:
                    nd_fact_args[0].extend([k.args[0]]*rvd[k])
                else:
                    nd_fact_args[1].extend([k.args[0]]*-rvd[k])
                rvd[k] = 0
        if not nd_fact_args[0] or not nd_fact_args[1]:
            return rv

        hit = False
        for m in range(2):
            i = 0
            while i < len(nd_fact_args[m]):
                ai = nd_fact_args[m][i]
                for j in range(i + 1, len(nd_fact_args[m])):
                    aj = nd_fact_args[m][j]

                    sum = ai + aj
                    if sum in nd_fact_args[1 - m]:
                        hit = True

                        nd_fact_args[1 - m].remove(sum)
                        del nd_fact_args[m][j]
                        del nd_fact_args[m][i]

                        rvd[binomial(sum, ai if count_ops(ai) <
                                count_ops(aj) else aj)] += (
                                -1 if m == 0 else 1)
                        break
                else:
                    i += 1

        if hit:
            return Mul(*([k**rvd[k] for k in rvd] + [factorial(k)
                    for k in nd_fact_args[0]]))/Mul(*[factorial(k)
                    for k in nd_fact_args[1]])
        return rv

    return bottom_up(expr, f)

# === atelier-kyo-manager/tools\scripts\inventory_manager.py ===
import pandas as pd
import json
from datetime import datetime
import os

# 設定
BASE_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
CSV_PATH = os.path.join(BASE_DIR, 'tools', 'buyma_products.csv')
INVENTORY_FILE = os.path.join(BASE_DIR, 'tools', 'inventory.json')

class InventoryManager:
    """在庫管理システム"""
    def __init__(self):
        self.inventory = {}
        self.load_inventory()

    def load_inventory(self):
        try:
            with open(INVENTORY_FILE, 'r', encoding='utf-8') as f:
                self.inventory = json.load(f)
        except FileNotFoundError:
            self.inventory = {}

    def save_inventory(self):
        with open(INVENTORY_FILE, 'w', encoding='utf-8') as f:
            json.dump(self.inventory, f, ensure_ascii=False, indent=2)

    def update_stock(self, item_id, quantity):
        self.inventory[item_id] = {
            "quantity": quantity,
            "last_updated": datetime.now().isoformat(),
            "status": "在庫あり" if quantity > 0 else "在庫切れ"
        }
        self.save_inventory()

    def get_stock(self, item_id):
        return self.inventory.get(item_id, {"quantity": 0, "status": "未登録"})

def detect_category(text):
    """カテゴリ自動判定ロジック（テキストのみ）"""
    if not isinstance(text, str):
        text = str(text)  # 念のため型変換
    text = text.lower()
    categories = {
        "バッグ": ["bag", "バッグ", "トート", "ショルダー"],
        "財布": ["wallet", "財布", "コインケース"],
        "時計": ["watch", "時計", "クロノグラフ"],
        "アクセサリー": ["jewelry", "ネックレス", "ブレスレット"],
        "服飾": ["coat", "ジャケット", "ドレス", "スカート"]
    }
    for cat, keywords in categories.items():
        if any(kw in text for kw in keywords):
            return cat
    return "その他"

def process_products(inventory):
    """商品データ処理メインロジック（自動アクセスなし）"""
    df = pd.read_csv(CSV_PATH, encoding='cp932')
    results = []

    for idx, row in df.iterrows():
        product = row.to_dict()
        item_id = product.get("商品管理番号", f"ITEM-{idx+1:03d}")

        # 在庫情報取得
        stock = inventory.get_stock(item_id)

        # カテゴリ自動判定（商品名や説明から）
        category = detect_category(product.get("商品名", "") + " " + product.get("商品説明", ""))

        # 発送方法判定
        price = product.get("販売価格", 0)
        weight = product.get("重量", 0)
        if price >= 500000:
            shipping_method = "DHL EXPRESS"
        elif weight > 10:
            shipping_method = "特別大型便"
        elif category == "バッグ":
            shipping_method = "BUYMA YAMATO"
        else:
            shipping_method = "標準発送"

        # データ統合
        processed = {
            **product,
            "在庫数": stock["quantity"],
            "在庫ステータス": stock["status"],
            "カテゴリ（自動判定）": category,
            "発送方法（自動判定）": shipping_method
        }
        results.append(processed)

        # 在庫更新（サンプル実装）
        inventory.update_stock(item_id, processed.get("在庫数", 0))

    return pd.DataFrame(results)

def main():
    inventory = InventoryManager()

    processed_df = process_products(inventory)
    output_path = os.path.join(BASE_DIR, 'tools', 'processed_products.csv')
    processed_df.to_csv(output_path, index=False, encoding='cp932')
    print(f"処理完了: {len(processed_df)}件の商品を出力")

    # 在庫アラート
    low_stock = [k for k,v in inventory.inventory.items() if v['quantity'] < 5]
    if low_stock:
        print(f"警告: 在庫不足商品 {len(low_stock)}件")

    inventory.save_inventory()

if __name__ == "__main__":
    main()

